import{_ as n,I as t,o as r,c as d,b6 as i,j as o,J as e,w as p}from"./chunks/framework.BUXTSoD9.js";const E=JSON.parse('{"title":"모던 AI 이미지 생성 SaaS 개발 실전","description":"","frontmatter":{},"headers":[],"relativePath":"ko-kr/stage-2/assignments/modern-landing-page/index.md","filePath":"ko-kr/stage-2/assignments/modern-landing-page/index.md"}'),h={name:"ko-kr/stage-2/assignments/modern-landing-page/index.md"},c={style:{margin:"32px 0"}};function b(k,a,g,u,m,f){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="모던-ai-이미지-생성-saas-개발-실전" tabindex="-1">모던 AI 이미지 생성 SaaS 개발 실전 <a class="header-anchor" href="#모던-ai-이미지-생성-saas-개발-실전" aria-label="Permalink to “모던 AI 이미지 생성 SaaS 개발 실전”">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to “개요”">​</a></h2><p>이 실전 프로젝트에서는 실제 PRD(제품 요구사항 문서)를 바탕으로 Midjourney 경험을 참고한 AI 이미지 생성 SaaS 제품을 처음부터 완성하게 됩니다. 요구사항 분석, 프로젝트 분해, 반복 개발, 연동 및 배포의 전 과정을 경험하게 됩니다.</p><p>이 프로젝트는 Stage 2의 종합 실전环节입니다. 앞선 장들에서 프론트엔드 페이지 디자인, 백엔드 API 개발, 데이터베이스 조작, 결제 연동 등의 개별 기술을 배웠습니다. 이 프로젝트에서는 그것들을 모두 연결하여 실행 가능한 제품 프로토타입을 전달해야 합니다.</p><h2 id="사전-지식" tabindex="-1">사전 지식 <a class="header-anchor" href="#사전-지식" aria-label="Permalink to “사전 지식”">​</a></h2><p>이 프로젝트를 시작하기 전에 다음 내용을 이미 숙지하고 있어야 합니다:</p><ul><li>프론트엔드 페이지 디자인 및 컴포넌트 라이브러리 사용 (<a href="./../../frontend/ui-design/">UI 디자인</a>, <a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리</a>)</li><li>백엔드 API 설계 및 개발 (<a href="./../../backend/ai-interface-code/">API 코드 작성</a>)</li><li>데이터베이스 기초와 Supabase (<a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a>)</li><li>결제 연동 (<a href="./../../backend/stripe-payment/">Stripe 결제 시스템</a>)</li><li>Git 워크플로우 및 배포 (<a href="./../../backend/git-workflow/">Git과 GitHub</a>, <a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포</a>)</li></ul><h2 id="학습-목표" tabindex="-1">학습 목표 <a class="header-anchor" href="#학습-목표" aria-label="Permalink to “학습 목표”">​</a></h2><p>이 실전을 완료하면 다음을 할 수 있게 됩니다:</p><ol><li>실제 PRD를 읽고 이해하여 개발 작업 목록을 추출하기</li><li>PRD를 기반으로 모듈을 분할하고 단계별 진행 계획을 수립하기</li><li>AI 보조를 활용하여 프론트엔드 골격 구축과 백엔드 API 개발을 완료하기</li><li>각 모듈에 대해 검증과 반복 최적화 수행하기</li><li>엔드투엔드 연동 테스트를 완료하고 프로젝트를 &quot;실행 가능&quot;에서 &quot;전달 가능&quot;으로 발전시키기</li></ol><h2 id="프로젝트-소개" tabindex="-1">프로젝트 소개 <a class="header-anchor" href="#프로젝트-소개" aria-label="Permalink to “프로젝트 소개”">​</a></h2><p>구축할 제품은 세 개의 하위 시스템을 포함하는 모던 AI 이미지 생성 SaaS 플랫폼입니다:</p><table tabindex="0"><thead><tr><th>하위 시스템</th><th>역할</th></tr></thead><tbody><tr><td><strong>공식 웹사이트</strong></td><td>제품 소개, 가격 정책, FAQ, 가입 전환</td></tr><tr><td><strong>사용자 워크스테이션</strong></td><td>Prompt 입력, 이미지 생성, 갤러리, 크레딧, 요금제, 커뮤니티 상호작용</td></tr><tr><td><strong>관리 대시보드</strong></td><td>사용자 관리, 작업 관리, 결제 관리, 콘텐츠 심사, SaaS 지표, 시스템 모니터링</td></tr></tbody></table><p>백엔드는 다음 핵심 역량을 지원해야 합니다: 사용자 인증, 이미지 생성 작업, OSS 오브젝트 스토리지, 크레딧과 요금제 결제, 이미지 소셜 상호작용, 운영 데이터 모니터링.</p><div class="tip custom-block"><p class="custom-block-title">PRD 입구</p><p>이 프로젝트의 요구사항 문서는 GitHub에 있습니다: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/ko-kr/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">PRD 보기</a></p></div>',15)),o("div",c,[e(s,null,{default:p(()=>[e(l,{active:0,items:[{title:"요구사항 분석",description:"PRD를 읽고 페이지, 모듈, 데이터 모델, 범위를 추출합니다"},{title:"골격 구축",description:"AI로 세 개의 프론트엔드 골격(www / app / admin)을 생성합니다"},{title:"반복 개발",description:"모듈별로 API, 권한, 결제, 모니터링을 추가합니다"},{title:"연동 및 배포",description:"엔드투엔드로 실행하고, 배포하여 데모를 준비합니다"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="제1부-요구사항-분석" tabindex="-1">제1부: 요구사항 분석 <a class="header-anchor" href="#제1부-요구사항-분석" aria-label="Permalink to “제1부: 요구사항 분석”">​</a></h2><h3 id="_1-1-prd-읽기" tabindex="-1">1.1 PRD 읽기 <a class="header-anchor" href="#_1-1-prd-읽기" aria-label="Permalink to “1.1 PRD 읽기”">​</a></h3><p>PRD 문서를 열고 다음 질문에 중점적으로 답해보세요:</p><ul><li>시스템에 몇 개의 진입점이 있는가? 각각 어떤 페이지를 포함하는가?</li><li>각 페이지의 핵심 기능은 무엇인가?</li><li>백엔드에 어떤 모듈과 데이터베이스 테이블이 포함되는가?</li><li>MVP 범위는 무엇인가? 첫 번째 버전에서 무엇을 하고 무엇을 하지 않는가?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>위 질문들에 명확한 답이 없다면, 코드 작성을 시작하지 마세요. 요구사항 이해가 불충분한 것은 재작업의 가장 흔한 원인입니다.</p></div><h3 id="_1-2-시스템-아키텍처-확인" tabindex="-1">1.2 시스템 아키텍처 확인 <a class="header-anchor" href="#_1-2-시스템-아키텍처-확인" aria-label="Permalink to “1.2 시스템 아키텍처 확인”">​</a></h3><p>PRD의 설명에 따라 시스템의 전체 아키텍처를 정리하세요:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;공식 웹사이트&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;사용자 워크스테이션&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;관리 대시보드&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;인증&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;이미지 생성 작업&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;OSS 오브젝트 스토리지&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;데이터베이스&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;결제 및 요금제&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;공유 / 좋아요 / 댓글 / 재게시&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;SaaS 지표 대시보드&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;API / DB / Provider 모니터링&quot;]</span></span></code></pre></div><p>자신만의 말로 아키텍처 다이어그램을 다시 그려보고, 시스템에 대한 이해가 완전한지 확인하세요.</p><h2 id="제2부-프로젝트-골격-구축" tabindex="-1">제2부: 프로젝트 골격 구축 <a class="header-anchor" href="#제2부-프로젝트-골격-구축" aria-label="Permalink to “제2부: 프로젝트 골격 구축”">​</a></h2><h3 id="_2-1-프론트엔드-페이지-생성" tabindex="-1">2.1 프론트엔드 페이지 생성 <a class="header-anchor" href="#_2-1-프론트엔드-페이지-생성" aria-label="Permalink to “2.1 프론트엔드 페이지 생성”">​</a></h3><p>AI를 사용하여 먼저 모든 페이지의 기본 구조와 가짜 데이터를 생성합니다. 이 단계의 목표는 정보 아키텍처와 라우팅을 구축하는 것이며, 실제 API를 연결할 필요는 없습니다.</p><p>프롬프트 참고:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>현재 PRD를 바탕으로 모던 AI 이미지 생성 SaaS의 프론트엔드 골격을 생성해 주세요.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>요구사항:</span></span>
<span class="line"><span>1. 세 개의 진입점으로 분할: www, app, admin</span></span>
<span class="line"><span>2. 공식 웹사이트 구성: 홈페이지, 가격 정책, FAQ</span></span>
<span class="line"><span>3. app 구성: 로그인, 회원가입, 생성 워크스테이션, 갤러리, 요금제, 크레딧, 커뮤니티, 작품 상세, 개인 센터</span></span>
<span class="line"><span>4. admin 구성: 관리 홈페이지, 사용자 관리, 작업 관리, 콘텐츠 관리, 요금제 관리, 결제 주문, 운영 설정, SaaS 지표, 시스템 모니터링</span></span>
<span class="line"><span>5. 먼저 페이지 구조와 가짜 데이터만 생성하고, 실제 API는 연결하지 않습니다</span></span>
<span class="line"><span>6. Midjourney를 참고한 깔끔하고 모던한 제품 느낌의 스타일</span></span></code></pre></div><h3 id="_2-2-페이지-구조-확인" tabindex="-1">2.2 페이지 구조 확인 <a class="header-anchor" href="#_2-2-페이지-구조-확인" aria-label="Permalink to “2.2 페이지 구조 확인”">​</a></h3><p>골격 생성 후 항목별 확인:</p><ul><li>[ ] 세 진입점의 라우팅이 독립적인가 (<code>/</code>, <code>/app</code>, <code>/admin</code>)</li><li>[ ] 페이지 수가 PRD와 일치하는가</li><li>[ ] 각 페이지가 정상적으로 접근 및 탐색이 가능한가</li><li>[ ] 가짜 데이터가 기본 UI 상태(목록, 빈 상태, 양식 등)를 표시하는가</li></ul><h2 id="제3부-반복-개발" tabindex="-1">제3부: 반복 개발 <a class="header-anchor" href="#제3부-반복-개발" aria-label="Permalink to “제3부: 반복 개발”">​</a></h2><h3 id="_3-1-모듈별-진행" tabindex="-1">3.1 모듈별 진행 <a class="header-anchor" href="#_3-1-모듈별-진행" aria-label="Permalink to “3.1 모듈별 진행”">​</a></h3><p>골격을 기반으로 다음 순서대로 모듈별로 기능을 추가합니다:</p><ol><li><strong>인증</strong>: 회원가입, 로그인, 역할 구분</li><li><strong>데이터베이스</strong>: 데이터 테이블 생성, 읽기/쓰기 API</li><li><strong>핵심 비즈니스</strong>: 이미지 생성 작업, 결과 저장</li><li><strong>OSS 스토리지</strong>: 이미지 업로드 및 접근</li><li><strong>결제</strong>: 요금제, 크레딧, Stripe 연동</li><li><strong>소셜 상호작용</strong>: 공유, 좋아요, 댓글</li><li><strong>관리 대시보드</strong>: 사용자 관리, 작업 관리, 콘텐츠 심사</li><li><strong>데이터 모니터링</strong>: SaaS 지표 대시보드, 시스템 모니터링</li></ol><p>각 모듈 완료 후 다음 표로 자체 점검:</p><table tabindex="0"><thead><tr><th>점검 항목</th><th>검증 방법</th></tr></thead><tbody><tr><td>페이지 일관성</td><td>페이지 수, 진입점, 기능이 PRD에 부합하는가</td></tr><tr><td>API 정확성</td><td>요청 파라미터, 응답 구조, 상태 처리가 합리적인가</td></tr><tr><td>권한 격리</td><td>일반 사용자와 관리자가 서로 격리되어 있는가</td></tr><tr><td>데이터 일관성</td><td>데이터베이스, OSS, 결제, 크레딧이 서로 일치하는가</td></tr><tr><td>데모 가능성</td><td>다른 사람에게 완전한 비즈니스 파이프라인을 데모할 수 있는가</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>AI가 생성한 내용이 PRD에서 벗어난 것을 발견하면, 전체 페이지를 뒤엎고 다시 시작하지 말고 특정 모듈만 수정하게 하세요.</p></div><h3 id="_3-2-역할과-분담" tabindex="-1">3.2 역할과 분담 <a class="header-anchor" href="#_3-2-역할과-분담" aria-label="Permalink to “3.2 역할과 분담”">​</a></h3><p>반복 과정에서 세 가지 역할을 동시에 수행해야 합니다:</p><ul><li><strong>제품 매니저</strong>: 각 모듈의 기능이 PRD에 부합하는지 확인</li><li><strong>기술 리더</strong>: 구현 방안이 합리적인지 확인</li><li><strong>테스트 엔지니어</strong>: 기능이 정상적으로 실행되는지 확인</li></ul><h2 id="제4부-연동-및-배포" tabindex="-1">제4부: 연동 및 배포 <a class="header-anchor" href="#제4부-연동-및-배포" aria-label="Permalink to “제4부: 연동 및 배포”">​</a></h2><h3 id="_4-1-엔드투엔드-테스트" tabindex="-1">4.1 엔드투엔드 테스트 <a class="header-anchor" href="#_4-1-엔드투엔드-테스트" aria-label="Permalink to “4.1 엔드투엔드 테스트”">​</a></h3><p>마지막 단계의 중점은 새 페이지를 추가하는 것이 아니라, 완전한 비즈니스 파이프라인을 실행하는 것입니다. 최소한 다음 시나리오를 검증하세요:</p><ul><li>회원가입 → 크레딧 구매 → 이미지 생성 → 기록 확인 → 공유 상호작용</li><li>관리자 로그인 → 사용자 데이터 확인 → 작업 통계 확인 → 시스템 모니터링 확인</li></ul><h3 id="_4-2-배포" tabindex="-1">4.2 배포 <a class="header-anchor" href="#_4-2-배포" aria-label="Permalink to “4.2 배포”">​</a></h3><p>프로젝트를 공개 네트워크 환경에 배포하고 다음을 확인하세요:</p><ul><li>환경 변수 구성이 완전한가</li><li>로그인 콜백 주소가 올바른가</li><li>결제 콜백 주소가 올바른가</li><li>페이지에 누락된 로딩, 빈 상태, 오류 메시지가 없는가</li></ul><p>배포 튜토리얼 참고: <a href="./../../backend/git-workflow/">Git 및 GitHub 워크플로우</a>, <a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포 방법</a>.</p><h2 id="산출물" tabindex="-1">산출물 <a class="header-anchor" href="#산출물" aria-label="Permalink to “산출물”">​</a></h2><p>이 프로젝트를 완료한 후 다음을 제출해야 합니다:</p><ul><li>[ ] 접근 가능한 온라인 데모 링크</li><li>[ ] 소스 코드 저장소 링크 (README 포함)</li><li>[ ] PRD 문서</li><li>[ ] 핵심 페이지 스크린샷 (공식 웹사이트 홈페이지, 이미지 생성 워크스테이션, 갤러리, 요금제 페이지, 관리 홈페이지)</li><li>[ ] 60초 데모 영상 (회원가입 → 생성 → 확인 → 관리 대시보드 포함)</li></ul><p>README에는 최소한 다음이 포함되어야 합니다: 프로젝트 소개, 핵심 페이지 설명, 기술 스택, 로컬 실행 단계, 환경 변수 목록.</p><h2 id="평가-기준" tabindex="-1">평가 기준 <a class="header-anchor" href="#평가-기준" aria-label="Permalink to “평가 기준”">​</a></h2><table tabindex="0"><thead><tr><th>영역</th><th>기본 요구사항</th><th>심화 요구사항</th></tr></thead><tbody><tr><td>PRD 정합성</td><td>페이지, 기능, 데이터 구조가 기본적으로 PRD에 부합</td><td>각 설계 결정과 PRD의 대응 관계를 명확히 설명할 수 있음</td></tr><tr><td>제품 루프</td><td>회원가입 → 크레딧 구매 → 이미지 생성 → 기록 확인 → 공유 상호작용이 실행 가능</td><td>결제 상태, 크레딧 잔액, 생성 횟수 데이터가 일치함</td></tr><tr><td>관리 기능</td><td>사용자, 작업, 결제, 콘텐츠 관리를 확인할 수 있음</td><td>SaaS 지표 대시보드와 시스템 모니터링 페이지가 완전히 사용 가능함</td></tr><tr><td>엔지니어링 완성도</td><td>프론트엔드, 백엔드, 데이터베이스, OSS, 결제 체인이 연결됨</td><td>오류 처리, 빈 상태, 로딩 상태가 있음</td></tr><tr><td>전달 품질</td><td>배포 가능, 실행 가능</td><td>README가 명확하고, 데모 영상 구조가 완전함</td></tr></tbody></table><h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 디자인</a></li><li><a href="./../../frontend/multi-product-ui/">UI 디자인 가이드를 참고하여 페이지와 버튼 디자인하기</a></li><li><a href="./../../frontend/llm-skills-beautiful/">LLM과 Skills로 인터페이스를 아름답게 만들기</a></li><li><a href="./../../frontend/design-to-code/">디자인 프로토타입에서 프로젝트 코드까지</a></li><li><a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리로 인터페이스 업데이트하기</a></li><li><a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a></li><li><a href="./../../backend/ai-interface-code/">대형 언어 모델로 API 코드 및 문서 작성하기</a></li><li><a href="./../../backend/git-workflow/">Git 및 GitHub 워크플로우</a></li><li><a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포 방법</a></li><li><a href="./../../backend/stripe-payment/">Stripe 등 결제 시스템 연동 방법</a></li></ul>`,43))])}const _=n(h,[["render",b]]);export{E as __pageData,_ as default};
